class Solution {
public:
    int maxDistToClosest(vector<int>& seats) {
        int n = seats.size(), last = -1, best = 0;
        for (int i = 0; i < n; i++) {
            if (!seats[i]) continue;
            best = last < 0 ? i : max(best, (i - last) / 2);
            last = i;
        }
        return max(best, n - 1 - last);
    }
};
